$ErrorActionPreference='Stop'
$root='E:\IIOP';$localSecrets=Join-Path $root 'scripts\dev\local-secrets.ps1';if(Test-Path $localSecrets){. $localSecrets};$state='E:\IIOP-data\dev\backend';$java=Join-Path $env:JAVA_HOME 'bin\java.exe';if(!(Test-Path $java)){throw 'JAVA_HOME must point to a JDK with bin\\java.exe'};New-Item -ItemType Directory -Force -Path $state|Out-Null
$services=@(@{name='gateway';module='iiop-gateway';port=8080},@{name='auth';module='iiop-auth';port=9201},@{name='device';module='iiop-device';port=9202},@{name='inspection';module='iiop-inspection';port=9203},@{name='maintenance';module='iiop-maintenance';port=9204},@{name='ai';module='iiop-ai';port=9205})
foreach($service in $services){$pidFile=Join-Path $state "$($service.name).pid";if(Test-Path $pidFile){$existing=Get-Process -Id ([int](Get-Content $pidFile)) -ErrorAction SilentlyContinue;if($existing){Write-Output "$($service.name): already running";continue};Remove-Item -LiteralPath $pidFile -Force};$jar=Join-Path $root "backend\$($service.module)\target\$($service.module)-1.0.0-SNAPSHOT.jar";if(!(Test-Path $jar)){throw "Missing built jar: $jar"};$args=@('-jar',$jar);if($service.name -eq 'ai'){$args+=@('--spring.profiles.active=local')};$log=Join-Path $state "$($service.name).log";$errorLog=Join-Path $state "$($service.name).err.log";$process=Start-Process -FilePath $java -ArgumentList $args -RedirectStandardOutput $log -RedirectStandardError $errorLog -PassThru -WindowStyle Hidden;$process.Id|Set-Content -LiteralPath $pidFile;Write-Output "$($service.name): started ($($process.Id))"}
